<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import DashboardPageHeader from '@/components/shared/DashboardPageHeader.vue'
import AppButton from '@/components/ui/AppButton.vue'
import TagEditor from '@/components/shared/TagEditor.vue'
import MarkdownBody from '../components/MarkdownBody.vue'
import { newId, today, useWorkspaceStore, type Document } from '@/stores/workspace'
const store = useWorkspaceStore()
const route = useRoute(); const router = useRouter()
const query = ref(''); const filter = ref('all'); const draft = ref<Document | null>(null); const notice = ref(''); const pendingId = ref<number | null>(null)
const documents = computed(() => store.documents.filter(d => (filter.value === 'trash' ? !!d.trashedAt : !d.trashedAt && (filter.value === 'all' || d.visibility === filter.value)) && `${d.title} ${d.tags.join(' ')}`.toLowerCase().includes(query.value.toLowerCase())))
function edit(doc: Document) { draft.value = JSON.parse(JSON.stringify(doc)); notice.value = ''; pendingId.value = null }
function create() { draft.value = { id: newId(), slug: `note-${newId()}`, title: '', summary: '', excerpt: '', kind: store.settings.defaultNoteKind, publishedAt: today(), displayDate: today(), readingTime: '1 min', tags: [], featured: false, content: '', visibility: store.settings.defaultNoteVisibility, updatedAt: today(), trashedAt: null }; notice.value = '' }
async function save() {
  if (!draft.value?.title.trim()) { notice.value = 'Please enter a title.'; return }
  const doc = JSON.parse(JSON.stringify(draft.value)) as Document
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(doc.slug)) { notice.value = 'Slug must contain lowercase letters, numbers and hyphens.'; return }
  if (store.documents.some(n => n.id !== doc.id && n.slug === doc.slug)) { notice.value = 'This slug is already used by another note.'; return }
  const saved = await store.saveDocument(doc)
  draft.value = JSON.parse(JSON.stringify(saved))
  const paper = store.papers.find(p => p.id === Number(route.query.paper))
  if (paper) await store.linkNote(paper.id, saved.id, true)
  notice.value = paper ? 'Saved and linked to the recommended paper.' : 'Saved to the workspace database.'
}
async function trash() { const doc = store.documents.find(d => d.id === pendingId.value); if (doc) await store.trashDocument(doc.id); pendingId.value = null; draft.value = null; notice.value = 'Moved to Trash. Existing paper links are retained for restoration.' }
function openFromRoute() { const doc = store.documents.find(d => d.id === Number(route.query.note)); if (doc) edit(doc); else if (route.query.new) create() }
async function restore() { if (!draft.value) return; await store.restoreDocument(draft.value); draft.value.trashedAt = null; notice.value = 'Restored.' }
watch(() => route.fullPath, openFromRoute, { immediate: true })
</script>
<template><div><DashboardPageHeader title="Documents" description="Write notes, organize your knowledge, and choose what appears publicly."><AppButton @click="create">New note</AppButton></DashboardPageHeader><p v-if="notice" class="feedback" role="status">{{ notice }}</p><div class="manager-split"><section class="record-list"><input v-model="query" aria-label="Search documents" placeholder="Search titles or tags…" /><select v-model="filter" aria-label="Document visibility filter"><option value="all">All active notes</option><option value="private">Private</option><option value="public">Public</option><option value="unlisted">Unlisted</option><option value="trash">Trash</option></select><button v-for="doc in documents" :key="doc.id" class="record-row" :class="{ active: draft?.id === doc.id }" @click="edit(doc)"><strong>{{ doc.title }}</strong><small>{{ doc.kind }} · {{ doc.trashedAt ? 'Trash' : doc.visibility }} · {{ doc.updatedAt }}</small><span>{{ doc.tags.join(' · ') }}</span></button><p v-if="!documents.length" class="empty-hint">No documents in this view.</p></section><section v-if="draft" class="record-editor"><template v-if="draft.trashedAt"><h2>{{ draft.title }}</h2><p>This note is in Trash and is not visible publicly.</p><AppButton @click="restore">Restore note</AppButton></template><form v-else @submit.prevent="save"><div class="editor-heading"><h2>{{ store.documents.some(d => d.id === draft?.id) ? 'Edit note' : 'New note' }}</h2><AppButton type="submit">Save note</AppButton></div><label>Title<input v-model="draft.title" required /></label><div class="field-grid"><label>URL slug<input v-model="draft.slug" required /></label><label>Type<select v-model="draft.kind"><option>Research Note</option><option>Essay</option><option>Guide</option><option>Reference</option></select></label><label>Visibility<select v-model="draft.visibility"><option value="private">Private</option><option value="public">Public</option><option value="unlisted">Unlisted</option></select></label><label>Publication date<input v-model="draft.publishedAt" type="date" /></label></div><label>Summary<textarea v-model="draft.summary" rows="2" /></label><TagEditor v-model="draft.tags" /><label class="check-field"><input v-model="draft.featured" type="checkbox" /> Feature on homepage</label><div class="markdown-editor"><label>Markdown<textarea v-model="draft.content" rows="18" placeholder="# Start writing…" /></label><section><p class="field-label">Preview</p><MarkdownBody :content="draft.content" /></section></div><p class="muted-copy">Private notes are available in the workspace. Public notes appear in the library. Unlisted notes are reachable by their link.</p><div class="editor-actions"><AppButton type="submit">Save note</AppButton><RouterLink v-if="store.documents.some(d => d.id === draft?.id) && draft.visibility !== 'private'" :to="`/notes/${draft.slug}`">Open reading page ↗</RouterLink><button v-if="store.documents.some(d => d.id === draft?.id)" type="button" class="text-action danger" @click="pendingId = draft.id">Move to Trash</button></div><div v-if="pendingId" class="inline-confirm"><span>Move this note to Trash? You can restore it later.</span><AppButton @click="trash">Move to Trash</AppButton><button type="button" @click="pendingId = null">Cancel</button></div></form></section><section v-else class="record-editor empty-state"><h2>Your research notebook</h2><p>Select a note or create one. Paper links are optional, and one paper can link to multiple notes.</p></section></div></div></template>
